SELECT '01M6VN593M26HR44A2QBT6RV47', 'audiologist/lindsay-collins', 'published', '2026-11-08T12:00:00.000Z', '2026-11-08T12:00:00.000Z', '2026-11-08T12:00:00.000Z', 1, 'en', '01M6VN593M26HR44A2QBT6RV47',
  'Lindsay Collins, Au.D.', '/audiologist/lindsay-collins/', 'Lindsay Collins, Au.D. | New Leaf Hearing Care', 'Lindsay Collins, Au.D., CCC-A, CH-TM is a certified audiologist providing hearing tests, hearing aids, and other hearing care services in Littleton, CO.', 'Lindsay Collins, Au.D.', 'Audiologist',
  '[{"_type":"block","_key":"lc01","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"lc01s","text":"Education and Credentials","marks":[]}]},{"_type":"block","_key":"lc02","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"lc02s","text":"Doctor of Audiology, Texas Tech University Health Sciences Center, Lubbock, TX. Bachelor of Science, University of Arizona. Certificate of Clinical Competence in Audiology (CCC-A), American Speech-Language-Hearing Association (ASHA). Certificate Holder–Tinnitus Management (CH-TM), American Board of Audiology (ABA).","marks":[]}]},{"_type":"block","_key":"lc03","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"lc03s","text":"Why Hearing Care","marks":[]}]},{"_type":"block","_key":"lc04","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"lc04s","text":"Lindsay’s passion for hearing care was inspired by watching family and friends live with hearing loss and seeing how it can impact communication, relationships and connection. As someone who loves building relationships and says she has “never met a stranger,” she is passionate about helping others hear the world around them and stay connected to the people in their lives.","marks":[]}]},{"_type":"block","_key":"lc05","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"lc05s","text":"Clinical Experience","marks":[]}]},{"_type":"block","_key":"lc06","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"lc06s","text":"Throughout her training, Lindsay completed clinical rotations in a variety of settings, including hospitals and private practices, gaining experience caring for patients of all ages with diverse hearing and tinnitus needs. She takes a compassionate, patient-centered approach to helping each person find solutions that improve their quality of life.","marks":[]}]},{"_type":"block","_key":"lc07","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"lc07s","text":"Prior to New Leaf Hearing Care, Lindsay worked in a variety of hearing care settings, including providing telecare support for over-the-counter hearing aids, caring for patients with tinnitus and working in an ENT center.","marks":[]}]},{"_type":"block","_key":"lc08","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"lc08s","text":"Personal","marks":[]}]},{"_type":"block","_key":"lc09","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"lc09s","text":"Hearing care is also personal for Lindsay. Her mom has worn hearing aids for many years and has been Lindsay’s longtime patient.","marks":[]}]},{"_type":"block","_key":"lc10","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"lc10s","text":"Originally from Dallas, Texas, Lindsay now lives in Centennial, Colorado. Outside of the center, Lindsay is a proud “Swiftie” who loves getting lost in a good book. She enjoys spending time with her husband and two sons, whether they’re camping, hiking or relaxing at home with their dogs, cats and pet hedgehog.","marks":[]}]}]',
  '{"provider":"external","id":"audiologist-lindsay-collins","src":"/assets/new-leaf-hearing-care-lindsay.webp","alt":"Lindsay Collins, Au.D.","filename":"new-leaf-hearing-care-lindsay.webp"}'
